package de.mcstack.craftcore;
import org.junit.jupiter.api.Test;
import java.sql.*;
import java.time.*;
import static org.junit.jupiter.api.Assertions.*;
class MotivationStoreTest {
 @Test void streakAndRanks(){LocalDate d=LocalDate.of(2026,10,28);assertEquals(1,MotivationStore.nextStreak(null,0,d));assertEquals(0,MotivationStore.nextStreak(d,4,d));assertEquals(5,MotivationStore.nextStreak(d,4,d.plusDays(1)));assertEquals(1,MotivationStore.nextStreak(d,4,d.plusDays(2)));assertEquals(0,MotivationStore.nextStreak(d,4,d.minusDays(1)));assertEquals("",MotivationStore.rank(17999));assertEquals("Neuling",MotivationStore.rank(18000));assertEquals("Legende",MotivationStore.rank(300*3600L));assertEquals(1000,MotivationStore.crossed(999,1000,new long[]{100,1000}));}
 @Test void loginIsAtomicAndOncePerDay() throws Exception {try(Connection c=DriverManager.getConnection("jdbc:h2:mem:motivation;MODE=MySQL;DB_CLOSE_DELAY=-1")){try(Statement q=c.createStatement()){q.execute("CREATE TABLE accounts(uuid VARCHAR(36) PRIMARY KEY,balance BIGINT NOT NULL)");q.execute("CREATE TABLE motivation(uuid VARCHAR(36) PRIMARY KEY,login_day DATE,streak INT DEFAULT 0 NOT NULL,seconds_played BIGINT DEFAULT 0 NOT NULL,blocks BIGINT DEFAULT 0 NOT NULL,kills BIGINT DEFAULT 0 NOT NULL,badge7 BOOLEAN DEFAULT FALSE NOT NULL,badge30 BOOLEAN DEFAULT FALSE NOT NULL,badge INT DEFAULT 0 NOT NULL)");}c.setAutoCommit(false);LocalDate d=LocalDate.of(2026,1,1);assertEquals(1,MotivationStore.login(c,"p",d));c.rollback();assertEquals(1,MotivationStore.login(c,"p",d));c.commit();assertEquals(0,MotivationStore.login(c,"p",d));for(int i=1;i<30;i++){assertEquals(i+1,MotivationStore.login(c,"p",d.plusDays(i)));}c.commit();var s=MotivationStore.lock(c,"p");assertTrue(s.badge7());assertTrue(s.badge30());assertEquals(30,s.streak());try(Statement q=c.createStatement();ResultSet r=q.executeQuery("SELECT balance FROM accounts WHERE uuid='p'")){assertTrue(r.next());assertEquals(30000,r.getLong(1));}assertEquals(1,MotivationStore.login(c,"p",d.plusDays(31)));assertTrue(MotivationStore.lock(c,"p").badge30());}}
}
